
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_1b_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_1b", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.434642194781558e+00, -3.367361543167327e+00, -3.273130179831854e+00, -3.142692322818836e+00, -2.965163386197929e+00, -2.729361629600267e+00, -2.427024976782163e+00, -2.059004758992538e+00, -1.645293091623466e+00, -1.233786253710475e+00, -8.581821246874045e-01, -5.982108418037887e-01, -5.213775093284819e-01, -4.289060435973182e-01, -3.104242494367389e-01, -1.985805413384941e-01, -1.274147154479672e-01, -6.116380760215702e-02, -1.524797516052916e-02, -1.858057603026091e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


